using System.Numerics;
using System.Text.Json;
using LastEpochLAN.Mod.OfflineTools.WorldAssist;
using Mono.Cecil;

var checks=new List<string>();
void Check(bool ok,string label){if(!ok)throw new Exception("FAIL: "+label);checks.Add(label);Console.WriteLine("PASS: "+label);}
bool Near(float a,float b)=>MathF.Abs(a-b)<.001f;
var examples=new[]{"ShrineVisuals","Blood-Filled Crystal","NemesisEncounterGameplayObject","TimeBeastEggs","RunePrison","ObserverWindow","standard chest","Boss Chest","OneShotCache","cemetery_entrance","TimeBeastRift","icon_MainQuest","Tomb Exit","Unknown Object"};
for(int i=0;i<14;i++)Check(AssistRules.Classify(examples[i])==(TargetKind)i,"native key classification: "+examples[i]);
Check(AssistRules.Classify("BLOOD CRYSTAL")==TargetKind.BloodCrystal,"case insensitive blood crystal");
Check(AssistRules.Classify("localized label",transition:true)==TargetKind.Transition,"localized transition classified from component");
Check(AssistRules.Classify("localized label",quest:true)==TargetKind.Quest,"localized quest classified from native indicator");
Check(AssistRules.Classify("Nemesis Chest",quest:true,transition:true)==TargetKind.Nemesis,"specific encounter has priority over generic labels");
var table=AssistRules.ParseRadii("Flaming Ground=4;Cone=cone:60:8;German=kegel:90:6;Arrow=projectile:0.75:12;bad=NaN;bad2=-3;bad3=0;bad4=cone:361:2;bad5=Infinity;bad6=projectile:1:81;bad7;X=4:5",out int invalid);
Check(table.Count==4 && invalid==8,"invalid and nonfinite radius entries rejected without losing valid entries");
Check(table["flaming ground"]==new HazardSpec(HazardShape.Ring,4),"case insensitive ability radius override");
Check(table["Cone"]==new HazardSpec(HazardShape.Cone,8,60,8),"cone has full opening angle and length");
Check(table["German"].Shape==HazardShape.Cone,"reference DLL cone syntax supported");
Check(table["Arrow"]==new HazardSpec(HazardShape.Projectile,.75f,0,12),"projectile path radius and length parsed");
Check(AssistRules.ParseRadii("x=1; X=3",out invalid)["x"].Radius==3 && invalid==0,"last explicit ability override wins");
Check(AssistRules.ParseRadii(null,out invalid).Count==0 && invalid==0,"empty radius table retains fallback behavior");
var settings=new WorldAssistSettings();settings.Normalize();
Check(settings.Styles.Length==14 && settings.Styles.Select(s=>s.Colour).Distinct().Count()==14,"fourteen independently coloured target types");
Check(settings.Styles[1].Arrow && settings.Styles[2].Arrow && settings.Styles[11].Arrow && !settings.Styles[13].Arrow,"edge arrows default to important encounters and quest targets");
Check(!settings.Styles[6].Path && !settings.Styles[13].Path && settings.Styles[11].Path,"auto-route ignores miscellaneous clutter until explicitly selected");
settings.Styles[0].World=false;settings.Styles[0].Arrow=false;settings.Styles[0].Map=false;settings.Styles[0].Minimap=false;settings.Styles[0].Path=false;
Check(settings.Styles[1].World && settings.Styles[1].Path,"target controls do not alias other types");
var restored=JsonSerializer.Deserialize<WorldAssistSettings>(JsonSerializer.Serialize(settings));
Check(!restored.Styles[0].World && restored.Styles[1].Map,"per-type controls survive save/load");
settings.Styles=null;settings.Range=float.NaN;settings.AreaRadius=float.PositiveInfinity;settings.ProjectileRadius=-4;settings.ProjectileLength=1000;settings.AbilityRadii=null;settings.Normalize();
Check(settings.Styles.Length==14 && settings.Styles.All(s=>s!=null),"old or incomplete config restores all types");
Check(settings.Range==500 && settings.AreaRadius==2 && Near(settings.ProjectileRadius,.1f) && settings.ProjectileLength==80,"invalid numeric settings bounded");
Check(settings.AbilityRadii=="","null radius settings migrate safely");
settings.Styles[2]=null;settings.Normalize();Check(settings.Styles[2]!=null,"null per-type entry repaired");
var velocity=AssistRules.Velocity(Vector3.Zero,new Vector3(1,0,0),.05);
Check(Near(velocity.X,20),"velocity uses sample age");
Check(AssistRules.Velocity(Vector3.Zero,new Vector3(20,0,0),.05)==Vector3.Zero,"teleport clears prediction velocity");
Check(AssistRules.Velocity(Vector3.Zero,Vector3.One,0)==Vector3.Zero,"duplicate timestamp cannot produce nonfinite motion");
Check(AssistRules.Velocity(Vector3.Zero,Vector3.One,1)==Vector3.Zero,"scene pause clears prediction velocity");
Check(AssistRules.Velocity(Vector3.Zero,new Vector3(float.NaN,0,0),.05)==Vector3.Zero,"invalid source coordinates rejected");
Check(Near(AssistRules.Predict(Vector3.Zero,velocity,1,1.016,true).X,.32f),"positions predicted to draw time");
Check(Near(AssistRules.Predict(Vector3.Zero,velocity,1,1.08,true).X,.8f),"prediction is capped to forty milliseconds");
Check(AssistRules.Predict(Vector3.Zero,velocity,1,2,true)==Vector3.Zero,"stale sample never drifts indefinitely");
Check(AssistRules.Predict(Vector3.Zero,velocity,1,.9,true)==Vector3.Zero,"clock discontinuity cannot reverse prediction");
Check(AssistRules.Predict(Vector3.One,velocity,1,1.02,false)==Vector3.One,"smoothing toggle draws raw sample");
var route=new[]{new Vector3(0,0,0),new Vector3(0,0,10),new Vector3(10,0,10)};
Check(AssistRules.TailStart(new Vector3(0,0,5),route)==1,"route tail starts on current corridor");
Check(AssistRules.TailStart(new Vector3(5,0,10),route)==2,"walked route corner is discarded");
Check(AssistRules.TailStart(Vector3.Zero,Array.Empty<Vector3>())==0,"empty route has no segment");
Vector2 a=new(-10,5),b=new(20,5);
Check(AssistRules.Clip(ref a,ref b,0,0,10,10) && a==new Vector2(0,5) && b==new Vector2(10,5),"map path clipped on both sides");
a=new(-1,0);b=new(-1,20);Check(!AssistRules.Clip(ref a,ref b,0,0,10,10),"parallel off-map path is hidden");
a=new(2,2);b=new(8,8);Check(AssistRules.Clip(ref a,ref b,0,0,10,10) && a==new Vector2(2,2) && b==new Vector2(8,8),"visible path retained");
a=new(float.NaN,0);b=Vector2.One;Check(!AssistRules.Clip(ref a,ref b,0,0,10,10),"nonfinite map projection never reaches drawing");
a=Vector2.Zero;b=Vector2.One;Check(!AssistRules.Clip(ref a,ref b,0,0,0,0),"hidden zero-size map rejects path");

string dll=args.Length>1?args[1]:"src/LastEpochLAN.Mod/bin/Release/net6.0/LastEpochLAN.dll";
using var assembly=AssemblyDefinition.ReadAssembly(dll);
var types=assembly.MainModule.Types;
var runtime=types.Single(t=>t.FullName.EndsWith(".WorldAssistRuntime"));
IEnumerable<string> Calls(string method)=>runtime.Methods.Single(m=>m.Name==method).Body.Instructions.Select(i=>i.Operand).OfType<MethodReference>().Select(m=>m.FullName);
Check(Calls("UpdatePath").Any(s=>s.Contains("NavMesh::CalculatePath")) && Calls("UpdatePath").Count(s=>s.Contains("NavMesh::SamplePosition"))==2,"actual mod samples mesh endpoints and uses native pathfinding");
Check(Calls("ValidatePathHead").Any(s=>s.Contains("NavMesh::Raycast")),"current route head checked for walls after player movement");
Check(!Calls("Draw").Any(s=>s.Contains("FindObjectsOfType")) && !Calls("ReadMapProjection").Any(s=>s.Contains("FindObjectsOfType")),"render callbacks never scan scene");
Check(Calls("Discover").Any(s=>s.Contains("WorldObjectClickListener::get_allListener")) && Calls("Discover").Any(s=>s.Contains("SynclessRandomEncounter::get_allInstances")),"actual source uses native target registries");
Check(Calls("IsEnemy").Any(s=>s.Contains("Alignment::IsFoe")) && Calls("IsEnemy").Any(s=>s.Contains("ActorSync::get_IsLocalPlayer")),"actual mod filters caster ownership and hostile alignment");
Check(Calls("LateUpdate").Any(s=>s.Contains("Motion::Sample")),"native visual motion sampled during late update");
Check(Calls("ReadMapProjection").Any(s=>s.Contains("RectTransformUtility::WorldToScreenPoint")) && Calls("ReadMapProjection").Any(s=>s.Contains("Time::get_frameCount")),"map calibration uses current native UI positions and frame identity");
Check(Calls("Clear").Any(s=>s.Contains("ClearMapProbes")) && Calls("Clear").Any(s=>s.Contains("ClearPath")),"scene cleanup removes map probes and stale routes");
var mapPatch=types.Single(t=>t.Name=="AssistMapFramePatch");
Check(mapPatch.CustomAttributes.Any(a=>a.AttributeType.Name=="HarmonyPatch") && mapPatch.Methods.Any(m=>m.Name=="Prefix") && mapPatch.Methods.Any(m=>m.Name=="Postfix"),"native map lifecycle has sampling and projection hooks");
var toolkit=types.Single(t=>t.Name=="OfflineToolkit");
Check(toolkit.Methods.Single(m=>m.Name=="Tick").Body.Instructions.Any(i=>i.Operand is MethodReference m && m.FullName.Contains("WorldAssistRuntime::Tick")),"world assist wired into toolkit tick");
Check(toolkit.Methods.Single(m=>m.Name=="SceneChanged").Body.Instructions.Any(i=>i.Operand is MethodReference m && m.FullName.Contains("WorldAssistRuntime::Clear")),"scene lifecycle wired to cleanup");
var lan=types.Single(t=>t.Name=="LanMod");
Check(lan.Methods.Single(m=>m.Name=="OnGUI").Body.Instructions.Any(i=>i.Operand is MethodReference m && m.FullName.Contains("WorldAssistRuntime::Draw")),"overlay wired into mod GUI");
var forbidden=new[]{"::SetDestination(","::Interaction(","::AttemptTrigger(","::UseAbility(","::Teleport(","::ReceiveRemoteDestroy("};
Check(!runtime.Methods.Where(m=>m.HasBody).SelectMany(m=>m.Body.Instructions).Select(i=>i.Operand).OfType<MethodReference>().Any(m=>forbidden.Any(m.FullName.Contains)),"display and path queries do not invoke movement, combat or interactions");
Console.WriteLine($"All {checks.Count} world assist checks passed; native rendering/gameplay not exercised.");
if(args.Length>0)File.WriteAllText(args[0],JsonSerializer.Serialize(new{passed=checks.Count,checks,nativeRenderingValidated=false,nativeGameplayValidated=false},new JsonSerializerOptions{WriteIndented=true}));
